arguments.command:
python -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx')
for ws in wb.worksheets:
    print('Sheet:', ws.title, 'dims:', ws.dimensions)
    for row in ws.iter_rows(min_row=1, max_row=25, max_col=4):
        for c in row:
            if c.value is not None:
                print(c.coordinate, repr(c.value))
" && echo budget.xlsx
